macro_rules! r0_7_0 {
    () => {
        # [doc = " Release 0.7.0 (2021-02-06)"] # [doc = ""] # [doc = " ## Breaking changes"] # [doc = ""] # [doc = " ### Loading functions are now `unsafe`"] # [doc = ""] # [doc = " A number of associated methods involved in loading a library were changed to"] # [doc = " be `unsafe`. The affected functions are: [`Library::new`], [`os::unix::Library::new`],"] # [doc = " [`os::unix::Library::open`], [`os::windows::Library::new`],"] # [doc = " [`os::windows::Library::load_with_flags`]. This is the most prominent breaking change in this"] # [doc = " release and affects majority of the users of `libloading`."] # [doc = ""] # [doc = " In order to see why it was necessary, consider the following snippet of C++ code:"] # [doc = ""] # [doc = " ```c++"] # [doc = " #include <vector>"] # [doc = " #include <iostream>"] # [doc = ""] # [doc = " static std::vector<unsigned int> UNSHUU = { 1, 2, 3 };"] # [doc = ""] # [doc = " int main() {"] # [doc = "     std::cout << UNSHUU[0] << UNSHUU[1] << UNSHUU[2] << std::endl; // Prints 123"] # [doc = "     return 0;"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " The `std::vector` type, much like in Rust's `Vec`, stores its contents in a buffer allocated on"] # [doc = " the heap. In this example the vector object itself is stored and initialized as a static"] # [doc = " variable – a compile time construct. The heap, on the other hand, is a runtime construct. And"] # [doc = " yet the code works exactly as you'd expect – the vector contains numbers 1, 2 and 3 stored in"] # [doc = " a buffer on heap. So, _what_ makes it work out, exactly?"] # [doc = ""] # [doc = " Various executable and shared library formats define conventions and machinery to execute"] # [doc = " arbitrary code when a program or a shared library is loaded. On systems using the PE format"] # [doc = " (e.g. Windows) this is available via the optional `DllMain` initializer. Various systems"] # [doc = " utilizing the ELF format take a slightly different approach of maintaining an array of function"] # [doc = " pointers in the `.init_array` section. A very similar mechanism exists on systems that utilize"] # [doc = " the Mach-O format."] # [doc = ""] # [doc = " For the C++ program above, the object stored in the `UNSHUU` global variable is constructed"] # [doc = " by code run as part of such an initializer routine. This initializer is run before the entry"] # [doc = " point (the `main` function) is executed, allowing for this magical behaviour to be possible."] # [doc = " Were the C++ code built as a shared library instead, the initialization routines would run as"] # [doc = " the resulting shared library is loaded. In case of `libloading` – during the call to"] # [doc = " `Library::new` and other methods affected by this change."] # [doc = ""] # [doc = " These initialization (and very closely related termination) routines can be utilized outside of"] # [doc = " C++ too. Anybody can build a shared library in variety of different programming languages and"] # [doc = " set up the initializers to execute arbitrary code. Potentially code that does all sorts of"] # [doc = " wildly unsound stuff."] # [doc = ""] # [doc = " The routines are executed by components that are an integral part of the operating system."] # [doc = " Changing or controlling the operation of these components is infeasible. With that in"] # [doc = " mind, the initializer and termination routines are something anybody loading a library must"] # [doc = " carefully evaluate the libraries loaded for soundness."] # [doc = ""] # [doc = " In practice, a vast majority of the libraries can be considered a good citizen and their"] # [doc = " initialization and termination routines, if they have any at all, can be trusted to be sound."] # [doc = ""] # [doc = " Also see: [issue #86]."] # [doc = ""] # [doc = " ### Better & more consistent default behaviour on UNIX systems"] # [doc = ""] # [doc = " On UNIX systems the [`Library::new`], [`os::unix::Library::new`] and"] # [doc = " [`os::unix::Library::this`] methods have been changed to use"] # [doc = " <code>[RTLD_LAZY] | [RTLD_LOCAL]</code> as the default set of loader options (previously:"] # [doc = " [`RTLD_NOW`]). This has a couple benefits. Namely:"] # [doc = ""] # [doc = " * Lazy binding is generally quicker to execute when only a subset of symbols from a library are"] # [doc = "   used and is typically the default when neither `RTLD_LAZY` nor `RTLD_NOW` are specified when"] # [doc = "   calling the underlying `dlopen` API;"] # [doc = " * On most UNIX systems (macOS being a notable exception) `RTLD_LOCAL` is the default when"] # [doc = "   neither `RTLD_LOCAL` nor [`RTLD_GLOBAL`] are specified. The explicit setting of the"] # [doc = "   `RTLD_LOCAL` flag makes this behaviour consistent across platforms."] # [doc = ""] # [doc = " ### Dropped support for Windows XP/Vista"] # [doc = ""] # [doc = " The (broken) support for Windows XP and Windows Vista environments was removed. This was"] # [doc = " prompted primarily by a similar policy change in the [Rust"] # [doc = " project](https://github.com/rust-lang/compiler-team/issues/378) but also as an acknowledgement"] # [doc = " to the fact that `libloading` never worked in these environments anyway."] # [doc = ""] # [doc = " ### More accurate error variant names"] # [doc = ""] # [doc = " Finally, the `Error::LoadLibraryW` renamed to [`Error::LoadLibraryExW`] to more accurately"] # [doc = " represent the underlying API that's failing. No functional changes as part of this rename"] # [doc = " intended."] # [doc = ""] # [doc = " [issue #86]: https://github.com/nagisa/rust_libloading/issues/86"] # [doc = " [`Library::new`]: crate::Library::new"] # [doc = " [`Error::LoadLibraryExW`]: crate::Error::LoadLibraryExW"] # [doc = " [`os::unix::Library::this`]: crate::os::unix::Library::this"] # [doc = " [`os::unix::Library::new`]: crate::os::unix::Library::new"] # [doc = " [`os::unix::Library::open`]: crate::os::unix::Library::new"] # [doc = " [`os::windows::Library::new`]: crate::os::windows::Library::new"] # [doc = " [`os::windows::Library::load_with_flags`]: crate::os::windows::Library::load_with_flags"] # [doc = " [`RTLD_NOW`]: crate::os::unix::RTLD_NOW"] # [doc = " [RTLD_LAZY]: crate::os::unix::RTLD_LAZY"] # [doc = " [RTLD_LOCAL]: crate::os::unix::RTLD_LOCAL"] # [doc = " [`RTLD_GLOBAL`]: crate::os::unix::RTLD_GLOBAL"] pub mod r0_7_0 { }
    };
}

r0_7_0!()